/// <summary>
/// desined from AVA
/// </summary>
/// <param name="sender">sender</param>
/// <param name="e">e</param>
[FormControlEventHandler(formControlStr(AVAEDIAddress, AVAEDIAddress_CityExt), FormControlEventType::Lookup)]
public static void AVAEDIAddress_CityExt_OnLookup(FormControl sender, FormControlEventArgs e)
{

    Args args = new Args(formStr(LogisticsAddressCityLookup));
    args.caller(sender.formRun());
    args.callerFormControl(sender);
    FormRun formRun = classfactory.formRunClass(args);
    formRun.init();
    FormDataSource      avaEDIAddress_ds = sender.dataSourceObject();
    avaEDIAddress_ds.object(fieldNum(AVAEDIAddress,CityExt)).performFormLookup(formRun,sender);
}

